    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_04054cfee1",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base fixa é de R$ 5.000,00, equivalente a 500000 centavos.",
