  },
  "custo_novo": {
    "estado": "exato",
    "valor": 530000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_0ad555e744",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Ao orçamento base de 500000 centavos soma-se a taxa única de troca de 30000 centavos. Como o término permanece em D10, não incide cobrança por extensão.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 30000,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_0ad555e744",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso estabelece uma taxa adicional única de R$ 300,00 não incluída no orçamento; não há outras alterações de custo aplicáveis.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A substituição mantém a disponibilidade do cartucho em D2 e foi aceita pela engenharia, sem readequação nem alteração do procedimento padrão. O término permanece em D10. O único acréscimo é a taxa de troca de R$ 300,00."
}

